// BottomSheet — Adw.BottomSheet
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles bottom-sheet with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface BottomSheetProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gfloat, from Adw.BottomSheet */
  align?: number

  /** Gtk.Widget, from Adw.BottomSheet */
  bottomBar?: ReactNode

  /** gboolean, from Adw.BottomSheet */
  canClose?: boolean

  /** gboolean, from Adw.BottomSheet */
  canOpen?: boolean

  /** Gtk.Widget, from Adw.BottomSheet */
  content?: ReactNode

  /** gboolean, from Adw.BottomSheet */
  fullWidth?: boolean

  /** gboolean, from Adw.BottomSheet */
  modal?: boolean

  /** gboolean, from Adw.BottomSheet */
  open?: boolean

  /** gboolean, from Adw.BottomSheet */
  revealBottomBar?: boolean

  /** Gtk.Widget, from Adw.BottomSheet */
  sheet?: ReactNode

  /** gboolean, from Adw.BottomSheet */
  showDragHandle?: boolean
}

export function BottomSheet({ className, children }: BottomSheetProps) {
  return (
    <div className={cn(className)}>
      {children}
    </div>
  )
}
